// Custom Worker entrypoint (https://opennext.js.org/cloudflare/howtos/custom-worker):
// re-uses the OpenNext-generated fetch handler and adds the collection cron.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { runCollection } from "./src/lib/collect";

interface Env {
  SNOW_KV: KVNamespace;
  AI: Ai;
  AI_GATEWAY_ID?: string;
  UDOT_API_KEY?: string;
  COLLECTOR_CONTACT?: string;
}

export default {
  fetch: handler.fetch,

  async scheduled(controller, env, ctx) {
    ctx.waitUntil(
      runCollection(env, { now: new Date(controller.scheduledTime) }).then((summary) => {
        const failed = summary.results.filter((r) => !r.ok);
        console.log(
          JSON.stringify({
            event: "collection",
            cron: controller.cron,
            durationMs: summary.durationMs,
            ok: summary.results.length - failed.length,
            skipped: summary.skipped,
            recommendation: summary.recommendation,
            dailySnow: summary.dailySnow,
            failed: failed.map((f) => ({ id: f.id, error: f.error })),
          }),
        );
      }),
    );
  },
} satisfies ExportedHandler<Env>;
